// AXUnresponsiveApps (ou un petit registre dédié) : pids dont AXEnhancedUserInterface reste à rétablir.
private var pendingEnhancedUI: Set<pid_t> = []
func deferRestore(_ pid: pid_t) { lock.withLock { _ = pendingEnhancedUI.insert(pid) } }
func takePendingRestore(_ pid: pid_t) -> Bool { lock.withLock { pendingEnhancedUI.remove(pid) != nil } }

// setFrames : début de groupe
if registry.takePendingRestore(pid), !registry.isQuarantined(pid) {
    let error = io.setValue(kCFBooleanTrue, of: Self.enhancedUserInterface, on: AXMessaging.application(pid))
    if registry.noteResult(error, pid: pid) || error != .success { registry.deferRestore(pid) }
}
// defer de fin de lot
defer {
    guard let enhancedUI, enhancedUI.restore else { return }
    if registry.isQuarantined(pid) { registry.deferRestore(pid); return }
    let error = io.setValue(kCFBooleanTrue, of: Self.enhancedUserInterface, on: enhancedUI.app)
    if registry.noteResult(error, pid: pid) || error != .success { registry.deferRestore(pid) }
}

